#!/bin/sh
# build.sh: the dashboard YACD that podkop-exp brings (podkop/files/usr/share/podkop/yacd), built
# again from its source: Yacd-meta at UPSTREAM with podkop-minimal.patch, in the image IMAGE
# (docker), as the user who runs it. Run it from the root of the repository; it needs git, docker
# and the network.
# The patch and removed.txt are regenerated by hand from a working copy (git diff --binary
# --diff-filter=AMR UPSTREAM HEAD; git diff --name-only --diff-filter=D UPSTREAM HEAD); the shim of
# the icons in the patch comes from feather-shim.py.
set -eu
UPSTREAM=24151c331027ff176b45ed417180c6f1220474a3
BUILD=podkop-exp-7
# the image the files were built with: another version of bun may resolve or bundle otherwise
IMAGE=oven/bun:1.4.4@sha256:1d22548f177f4ff38e0c15baa3c2c46c6c2060ba2d1bc573bb4720b407548f1d
ROOT=$(pwd)
OUT=$ROOT/podkop/files/usr/share/podkop/yacd
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
git clone -q https://github.com/MetaCubeX/Yacd-meta "$WORK/src"
git -C "$WORK/src" checkout -q "$UPSTREAM"
git -C "$WORK/src" rm -q $(cat "$ROOT/yacd/removed.txt")
git -C "$WORK/src" apply --binary "$ROOT/yacd/podkop-minimal.patch"
docker run --rm --user "$(id -u):$(id -g)" -e HOME=/tmp -v "$WORK/src:/w" -w /w "$IMAGE" sh -c "bun install --frozen-lockfile && bunx vite build"
rm -rf "$OUT"
mkdir -p "$OUT"
cp -R "$WORK/src/public/." "$OUT/"
cp "$ROOT/yacd/LICENSE" "$OUT/LICENSE"
# the build the backend tells the served copy by (src/backend/yacd)
printf 'Yacd-meta %s, %s\n' "$(echo $UPSTREAM | cut -c1-7)" "$BUILD" > "$OUT/.podkop-builtin"
du -sk "$OUT"
